output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Shopping carts must not be taken into single-file shelf aisles where the agent is between shelves.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_narrow_aisle_with_cart",
    "text": "An agent may not push a cart into a narrow shelf aisle; the cart must be left outside before entering.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S"
                ]
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileAisleWithCart"
    }
  },
  {
    "id": "no_cart_side_shelf_interaction",
    "text": "Shelf interactions from side-facing narrow shelf aisles must be done without a cart.",
    "abstraction": {
      "state_properties": {
        "sideShelfAccess": {
          "and": [
            "adjShelf",
            {
              "or": [
                "shelfE",
                "shelfW"
              ]
            },
            {
              "le": [
                "freeWidthH",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hasCart",
          "sideShelfAccess"
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever an agent parks a cart, they are obliged to retrieve it before leaving the store.",
    "abstraction": {
      "state_properties": {
        "wideOpenStagingArea": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                8
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart",
              "wideOpenStagingArea"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              },
              "wideOpenStagingArea"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "park_only_in_wide_open_area",
    "text": "Carts may only be parked in wide open staging areas, not in narrow aisles or beside shelves.",
    "abstraction": {
      "state_properties": {
        "wideOpenStagingArea": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                8
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "releaseCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "releaseCart",
          {
            "not": "wideOpenStagingArea"
          }
        ]
      }
    }
  },
  {
    "id": "take_cart_at_entrance_station",
    "text": "On entering the supermarket, an agent must collect a cart from the entrance cart station.",
    "abstraction": {
      "state_properties": {
        "cartStation": "at(1,7)",
        "entranceWideArea": {
          "and": [
            "cartStation",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                8
              ]
            }
          ]
        }
      },
      "events": {
        "takeCartAtStation": {
          "pre": {
            "and": [
              "INTERACT",
              "entranceWideArea",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeCartAtStation"
    }
  },
  {
    "id": "cart_lateral_moves_only_in_wide_aisles",
    "text": "When pushing a cart east or west, the agent must stay in a full-width horizontal aisle.",
    "abstraction": {
      "state_properties": {
        "fullWidthHorizontalAisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        },
        "lateralMove": {
          "or": [
            "E",
            "W"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "lateralMove",
          {
            "not": "fullWidthHorizontalAisle"
          }
        ]
      }
    }
  },
  {
    "id": "return_from_hand_carry_aisle",
    "text": "After entering a single-file shelf aisle without the cart, the agent must return to a wide staging area before continuing with the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "wideOpenStagingArea": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                8
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "enterHandCarryAisle": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              {
                "or": [
                  "N",
                  "S"
                ]
              }
            ]
          },
          "post": "singleFileShelfAisle"
        },
        "returnToStagingWithoutCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              {
                "or": [
                  "N",
                  "S"
                ]
              }
            ]
          },
          "post": "wideOpenStagingArea"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterHandCarryAisle",
      "discharge": "returnToStagingWithoutCart"
    }
  }
]
